-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.prayer_worth(p_ql double precision, p_hour double precision, p_prayer double precision)
 RETURNS double precision
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- The hour before the sun is properly up, and the one as it goes: those two.
  select prayer_favour()
       * (0.55 + greatest(greatest(0, 1 - abs(p_hour - 6) / 3),
                          greatest(0, 1 - abs(p_hour - 20) / 3)) * 0.75)
       * (0.6 + p_ql / 200)
       * (0.7 + p_prayer / 220)
$function$
